CAT = "ssvHours"; SEG = "HRS"
Q = [
('What are the regular hours for selling and serving liquor in a licensed establishment in Ontario?',
 '9 a.m. to 2 a.m.', ['11 a.m. to 1 a.m.', '8 a.m. to 3 a.m.', '10 a.m. to 2 a.m.'],
 'Licensed establishments may sell and serve liquor from 9:00 a.m. to 2:00 a.m., Monday to Sunday, unless the licence limits the hours further.'),
('By what time must every sign of liquor be cleared from tables on a regular night?',
 '2:45 a.m.', ['2:15 a.m.', '2:30 a.m.', '3:00 a.m.'],
 'All signs of liquor, including glasses and bottles, must be cleared 45 minutes after the end of service, which is 2:45 a.m. for most licences.'),
("On New Year's Eve, until what time may a licensed establishment sell and serve liquor?",
 '3 a.m. on January 1', ['2 a.m. on January 1', '4 a.m. on January 1', 'Midnight on December 31'],
 'On December 31, liquor may be sold and served from 9:00 a.m. until 3:00 a.m. on January 1, with signs of liquor cleared by 3:45 a.m.'),
('A licence says service ends at 1 a.m. By when must all drinks be cleared?',
 '1:45 a.m.', ['2:00 a.m.', '2:45 a.m.', '1:15 a.m.'],
 'Signs of liquor must be cleared 45 minutes after the end time on the licence. A licence condition can set an earlier end than 2 a.m.'),
('At 1:58 a.m. a server takes an order for a round. When must the round be served?',
 'Before 2:00 a.m.', ['By 2:15 a.m.', 'By 2:45 a.m.', 'Before last guest leaves'],
 'All orders must be served before 2:00 a.m. The 45 minutes after that is only for clearing, not for serving.'),
("Does the 2:00 a.m. end of service apply to the licensee's own staff after their shift?",
 'Yes, to everyone', ['No, staff are exempt', 'No, managers are exempt', 'Yes, except on weekends'],
 "The AGCO says the end of sale and service at 2:00 a.m. applies to everyone, including the licensee's staff and representatives."),
('In the autumn, clocks fall back from 2:00 a.m. to 1:00 a.m. What happens to service?',
 'Until 2:00 a.m. new time', ['Until the first 2:00 a.m.', 'Until 1:00 a.m. new time', 'All night, as an exception'],
 'The licensee may turn the clock back and keep selling until 2:00 a.m. new time, then has 45 minutes to clear signs of service.'),
('In the spring, clocks jump from 2:00 a.m. to 3:00 a.m. When must sale stop?',
 'At that moment', ['At 4:00 a.m. new time', 'At 3:45 a.m.', 'At 1:00 a.m.'],
 'Sale stops when the clock moves forward. The licensee then has 45 minutes to clear signs of service, even though the clock shows 3:00 a.m.'),
('A licence carries a condition limiting service to midnight. Which hours apply?',
 'The licence condition', ['The regular 2 a.m. end', 'Whichever is later', "The server's choice"],
 'Some licences carry conditions that further limit the regular hours. The stricter condition on the licence applies.'),
('Where may a licensed bar sell and serve liquor at any time of day?',
 'Past airport security', ['In a hotel lobby bar', 'On a golf course', 'At a sports stadium'],
 'Licensed establishments in the sterile area beyond passenger screening at certain designated Ontario airports may sell and serve at any time, unless a licence condition limits them.'),
('Where must a licensee keep liquor that is not currently being offered for sale?',
 'In a secure storage area', ['Behind the bar on open shelves', "In the staff's cars", "At the owner's home"],
 "The Registrar's standards require liquor not currently offered for sale to be stored in a secure storage area."),
('Where may a licensed bar buy the liquor it sells?',
 'The LCBO or Beer Store', ['A nearby corner store', "A guest's duty-free bottles", 'A home winemaker'],
 'Liquor kept or sold under a liquor sales licence must be bought under the licence from the LCBO, Brewers Retail (The Beer Store) or a brewery, or transferred from another licensed premises.'),
('Which of these counts as illegal liquor in a licensed bar?',
 'Smuggled foreign bottles', ['Wine bought at the LCBO', 'Beer from the Beer Store', 'Craft beer from a brewery'],
 'Illegal or bootleg liquor includes smuggled foreign products, home-made liquor, watered-down liquor, liquor not bought from the LCBO and personal imports.'),
('A bar infuses vodka with fruit to make a house special. When is this allowed?',
 'When guests are told', ['Never, it is adulteration', 'When made off-site', 'When sold as a double'],
 'Infusing liquor to create drinks or change its flavour is permitted under section 25(2) of Regulation 746/21, as long as the customer is informed.'),
('A guest bought a sealed bottle of wine at the LCBO and brings it into a bar to take home later. Is this allowed?',
 'Yes, if it stays sealed', ['No, it is never allowed', 'Yes, if they drink it there', 'Only with a special permit'],
 'Patrons may bring sealed, unopened liquor into an establishment if it stays sealed and they take it home (s. 39 of Regulation 746/21).'),
("A restaurant has a bring-your-own-wine endorsement. Who must open the guest's bottle?",
 'A staff member', ['The guest', 'Any adult guest', 'A sommelier only'],
 'The licensee or one of its employees must open the wine and serve it to the patrons who brought it, as if they had bought it there.'),
('Which wine may a guest bring under a bring-your-own-wine endorsement?',
 'Sealed, store-bought wine', ['Homemade wine', 'Sealed fortified wine', 'An opened bottle from home'],
 'Only sealed, unopened commercially made wine qualifies, such as a bottle bought at a store. Homemade, ferment-on-premises, wine pub and fortified wines are excluded.'),
('A guest has half a bottle of wine left after dinner. When may they take it home?',
 'Once staff securely close it', ['Never, it must be poured out', 'If they finish it in the car', 'If they pour it into a cup'],
 'An opened, unfinished bottle of commercially made wine may leave the premises if the licensee has securely closed it, for example with its original screw cap.'),
]
